"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.28577",title:"Cache Engineering for Agents",up:65,href:"https://arxiv.org/abs/2610.28577",abstract:"Large Language Model (LLM) agents can handle increasingly complex tasks, navigating long trajectories of observations and actions. As these trajectories grow, key-value (KV) cache I/O and storage become the dominant cost. Trajectories can also exceed the LLM's maximum context length, requiring control over active cache growth. Prior work uses context engineering to reduce cache size by trimming or summarizing history. However, modifying the trajectory prefix invalidates subsequent cached states and triggers costly re-prefilling of retained context. Task accuracy can also suffer when too little",pdfUrl:"https://arxiv.org/pdf/2610.28577",primaryCategory:"cs.CL",published:"2026-10-20T00:00:00Z"},{id:"2610.29989",title:"Looking Ahead: Modeling Future Evolution in Autoregressive Video Generation",up:59,href:"https://arxiv.org/abs/2610.29989",abstract:"Autoregressive video diffusion models generate videos chunk by chunk, yet producing plausible continuations does not guarantee that they capture how scenes evolve. Under teacher forcing, strong temporal redundancy may allow local visual continuity to serve as a shortcut for current-chunk denoising, reducing the pressure to model visual evolution. We introduce Future Chunk Prediction (FCP), an auxiliary objective jointly optimized with teacher-forced denoising that predicts temporally separated chunks without access to the intervening visual context. Drawing supervision directly from training v",pdfUrl:"https://arxiv.org/pdf/2610.29989",primaryCategory:"cs.CV",published:"2026-10-21T00:00:00Z"},{id:"2610.26828",title:"Agent World Model in the Wild: Computer-Use Agent Environment Synthesis",up:57,href:"https://arxiv.org/abs/2610.26828",abstract:"Agent learning is shifting from learning from human data toward learning through interaction with the world. However, scaling such learning directly in real-world computer systems is challenging and can introduce substantial security risks. We therefore propose Agent World Model in the Wild (WildAWM), a scalable pipeline for synthesizing controllable environments and tasks for training general computer-use agents (CUAs). Whereas existing approaches typically specialize in a single agent interaction interface, we construct executable environments that jointly support graphical user interfaces, ",pdfUrl:"https://arxiv.org/pdf/2610.26828",primaryCategory:"cs.AI",published:"2026-10-19T00:00:00Z"},{id:"2610.20538",title:"PrismaCoder: Pushing the Boundaries of Open Multimodal Code Intelligence through Decomposed Rubric Synthesis",up:45,href:"https://arxiv.org/abs/2610.20538",abstract:"Multimodal code intelligence connects the symbolic world of programs with the visual world their execution creates. Interest in this capability is burgeoning, as models are increasingly asked to produce charts, webpages, animations, and semi-structured documents. Recently, proprietary models have pushed far ahead, producing interactive artifacts even from a text description or a screenshot alone. Yet their data and training remain closed, and open progress is held back by the quantity and quality of available data and by the pipelines and methods for producing it. Quality is the harder of the ",pdfUrl:"https://arxiv.org/pdf/2610.20538",primaryCategory:"cs.CL",published:"2026-10-14T00:00:00Z"},{id:"2610.21114",title:"Spectral-Spatial Interpretation",up:34,href:"https://arxiv.org/abs/2610.21114",abstract:"Post-hoc image explanations usually show where a model looks using spatial heatmaps or indicate which channels matter using global channel scores. These separate views are limiting for multispectral data because channel relevance is often spatially localized and physically meaningful. We introduce Spectral-Spatial Interpretation (SSI), a full-grid attribution method over position-channel players (g,c). For each spatial position, SSI fixes the observed surrounding context, defines a conditional game over the channels at that position, and applies the Shapley value to this local game. The result",pdfUrl:"https://arxiv.org/pdf/2610.21114",primaryCategory:"cs.LG",published:"2026-10-15T00:00:00Z"},{id:"2610.17860",title:"Socratic Skill Learning: Interleaving Teaching and Practice for Transferable Agent Skills",up:29,href:"https://arxiv.org/abs/2610.17860",abstract:"Agent Skills improve LLM agents by making task knowledge reusable across sessions. Learning transferable Skills requires evidence about a procedure and its conditions of use, which a successful task attempt can leave untested. We introduce Socratic Skill Learning (SSL), which interleaves expert teaching with Student practice. An Educator guides investigation while the Student remains the sole environment operator and Skill author, able to question, test, and adapt advice. To test reuse beyond the learning task, we construct SkillTransferBench, with 35 task families and 408 executable cases, pa",pdfUrl:"https://arxiv.org/pdf/2610.17860",primaryCategory:"cs.AI",published:"2026-10-13T00:00:00Z"},{id:"2610.28402",title:"StreamEval: Evaluating Interactive Streaming Video Generation Models",up:28,href:"https://arxiv.org/abs/2610.28402",abstract:"As streaming video generation advances, enabling real-time interaction with generated video is becoming increasingly important. We introduce StreamEval, a unified benchmark for interactive streaming video generation spanning five tasks: avatar dialogue, avatar performance, world generation, instruction editing, and reference editing. StreamEval comprises 300 scripted test cases lasting 15-300s, each specifying initial assets, incrementally arriving multimodal requests, and explicit requirements for state changes and content preservation. Performance is assessed along four evaluation dimensions",pdfUrl:"https://arxiv.org/pdf/2610.28402",primaryCategory:"cs.CV",published:"2026-10-20T00:00:00Z"},{id:"2610.26659",title:"SpatialScout: Can VLM Agents Actively Explore and Map 3D Scenes?",up:22,href:"https://arxiv.org/abs/2610.26659",abstract:"Spatial intelligence requires agents to actively acquire visual evidence and integrate observations into a coherent representation of the three-dimensional world. Yet spatial question answering offers limited evidence of whether models can construct accurate metric maps through autonomous exploration. We introduce SpatialScout, a benchmark for evaluating vision-language model (VLM) agents on active object-level 3D mapping. SpatialScout comprises 80 diverse indoor scenes containing 3,140 target objects. Given an object inventory, RGB observations, camera calibration, and camera poses, agents co",pdfUrl:"https://arxiv.org/pdf/2610.26659",primaryCategory:"cs.CV",published:"2026-10-19T00:00:00Z"},{id:"2610.28589",title:"AgenticRoboRL: Bringing Coding-Agent Post-Training to Agentic Robotics",up:17,href:"https://arxiv.org/abs/2610.28589",abstract:"Agentic robotics systems combine planners with robot harnesses to perform complex manipulation tasks. Recent work improves these systems through better harnesses and external memory, but relies on powerful closed-source models as planners and does not improve the planners' own capabilities. In contrast, coding agents have improved substantially by post-training the model itself. We therefore investigate whether post-training can also improve robot planners. However, applying it across robot harnesses requires accommodating different execution mechanisms, including VLA skill invocation and cont",pdfUrl:"https://arxiv.org/pdf/2610.28589",primaryCategory:"cs.RO",published:"2026-10-20T00:00:00Z"},{id:"2610.28698",title:"Scaling in Games: Continued Pre-Training For Embodied Agents In Diverse Virtual Worlds",up:17,href:"https://arxiv.org/abs/2610.28698",abstract:"Scaling data, diversity and model capacity has improved embodied learning in physical environments, where diverse experiences remain grounded in shared physical laws. Whether these gains extend to virtual worlds with different visual styles, dynamics, controls, and objectives remains unclear. We investigate this question through a controlled study of continued pre-training (CPT) across three axes: data volume, diversity, and model size. Our 120 training configurations span four model sizes from 0.8B to 27B, six data budgets from 50 to 1,600 hours, and five mixtures ranging from Minecraft-only ",pdfUrl:"https://arxiv.org/pdf/2610.28698",primaryCategory:"cs.AI",published:"2026-10-20T00:00:00Z"},{id:"2610.29357",title:"Memory-Centric Continual Learning for AI Agents",up:17,href:"https://arxiv.org/abs/2610.29357",abstract:"Autonomous agents powered by foundation models can reason, plan, and use tools, but their fixed weights and context limits hinder sustained learning from experience over long-term deployment. While external memory systems attempt to bridge this gap, they mostly act as passive retrieval caches, evaluated primarily by whether they can recall stored facts or past interactions. Whether memory can drive genuine continual learning remains an open question. In this paper, we introduce Memory-Centric Continual Learning (MCCL), arguing that memory should be judged by whether it improves future actions,",pdfUrl:"https://arxiv.org/pdf/2610.29357",primaryCategory:"cs.CL",published:"2026-10-21T00:00:00Z"},{id:"2610.29997",title:"DONIC: Generalist Dexterous Bimanual Tracking Control from Human Demonstrations",up:17,href:"https://arxiv.org/abs/2610.29997",abstract:"Despite recent progress in dexterous reference tracking, existing models focus primarily on single-hand manipulation and a limited range of interactions, leaving the bimanual dexterous behaviors common in real life unaddressed. The scarcity of contact-rich bimanual manipulation data and the increased complexity of coordinating contacts make developing a generalist bimanual tracker particularly challenging. Therefore, we present 1) DONIC, the first generalist bimanual tracker jointly trained across operation categories and human-motion sources, together with 2) BiHOI, a multi-view dataset of 1,",pdfUrl:"https://arxiv.org/pdf/2610.29997",primaryCategory:"cs.RO",published:"2026-10-21T00:00:00Z"},{id:"2610.29680",title:"TraceForge: Distilling with Your Own Thinking",up:15,href:"https://arxiv.org/abs/2610.29680",abstract:"Using an LLM to generate training data for another is among the most general ways to train one, and it remains common practice. Some frontier teams have closed that route for their own models: what comes back is an answer, or a short summary, without the detailed reasoning trace behind it. That is a little ironic: they were themselves built on distilling human knowledge, and distilling an open-source model is still entirely routine; the restriction applies to their own outputs alone. Recent work recovers the hidden reasoning by replaying encrypted blocks across models. It somehow works, but it",pdfUrl:"https://arxiv.org/pdf/2610.29680",primaryCategory:"cs.AI",published:"2026-10-21T00:00:00Z"},{id:"2610.29441",title:"Sparsity Should Be ALLOTted by Output: Training-Free Allocation of Block-Sparse Attention for Video Diffusion Transformers",up:13,href:"https://arxiv.org/abs/2610.29441",abstract:"Full 3D attention is costly in video Diffusion Transformers. Block-sparse attention reduces this cost by computing only selected attention blocks. However, existing methods either overlook the potential to optimize sparsity allocation or rely on heuristic rules or local metrics to guide it. In this work, we observe that sparsifying attention in different layers and at different denoising steps affects final-video fidelity to substantially different degrees. Yet the identities of the most sensitive layer-step pairs remain nearly unchanged across inputs. Building on these findings, we propose Al",pdfUrl:"https://arxiv.org/pdf/2610.29441",primaryCategory:"cs.CV",published:"2026-10-21T00:00:00Z"},{id:"2610.30108",title:"Multimodal Embodied Agents: A Unified Capability-centric Perspective from Computer-Use to Robot-Use",up:13,href:"https://arxiv.org/abs/2610.30108",abstract:"Multimodal agents (MMAs) sustain interaction through reasoning, memory, tools, and feedback, most visibly as computer-use agents, while robotic systems (RSs) couple sensing and actuation under physical dynamics. We define multimodal embodied agents (MMEAs) as goal-directed systems that couple multimodal task reasoning with physical action and revise decisions from the resulting feedback. This raises a central question: what changes when a multimodal agent moves from computer-use to robot-use? We introduce PAPAV, a unified capability-centric framework of five recurring functions: Perceive the c",pdfUrl:"https://arxiv.org/pdf/2610.30108",primaryCategory:"cs.RO",published:"2026-10-21T00:00:00Z"},{id:"2610.28887",title:"Building AI Research Teams for Autonomous Discovery of Linear Attention Architectures",up:12,href:"https://arxiv.org/abs/2610.28887",abstract:"Autonomous agents can increasingly propose ideas, modify code, and run experiments, creating an opportunity to accelerate scientific discovery using teams of collaborative AI researchers. To escape local minima in the discovery, we propose to encourage orthogonal exploration by constructing the team using agents with varying expertise. However, realizing this design requires more than diverse backgrounds. When experiments are costly, a team can test only a limited number of ideas, thereby creating the need to balance exploration and exploitation when selecting a subset of researchers to propos",pdfUrl:"https://arxiv.org/pdf/2610.28887",primaryCategory:"cs.CL",published:"2026-10-20T00:00:00Z"},{id:"2610.16523",title:"EAU: Environment-Agent-User Co-evolution for Training User-Centric Agents",up:11,href:"https://arxiv.org/abs/2610.16523",abstract:"Training LLM agents to interact with users over multiple turns is challenging because the learning signal depends not only on the agent, but also on the user simulator and environment, which jointly shape the agent's experience. Simulated users can be stochastic or inconsistent, while environments may contain unreliable tools, incomplete state coverage, and incorrect verifiers. Prior work mainly addresses the resulting instability through reward shaping or denser supervision, while treating these components as fixed. We instead introduce EAU, a meta-agent framework for environment--agent--user",pdfUrl:"https://arxiv.org/pdf/2610.16523",primaryCategory:"cs.AI",published:"2026-10-12T00:00:00Z"},{id:"2610.28069",title:"Training the Whole Agent, Not Just the Model",up:11,href:"https://arxiv.org/abs/2610.28069",abstract:"Training coding agents typically updates the policy while keeping the harness fixed. During training, trajectories reveal flawed repair strategies and interaction problems that vary across tasks and change as the policy learns. We introduce HarnessAdapt-RL, which trains the policy and adapts its harness during reinforcement learning. For flawed repair strategies, a frozen teacher generates task-specific mechanism-level skills. For interaction problems recurring across tasks, a separate teacher model evolves tools and hooks, keeping each change only if it improves the observed pass rate or the ",pdfUrl:"https://arxiv.org/pdf/2610.28069",primaryCategory:"cs.SE",published:"2026-10-20T00:00:00Z"},{id:"2610.30120",title:"ALPS: Visual State Encoders for World Models",up:11,href:"https://arxiv.org/abs/2610.30120",abstract:"World models turn visual representations into predictions and actions. We argue that their visual foundation should combine physical-state information, native language alignment, and pixel reconstruction, so that a single representation can support prediction, instruction, and inspection. However, existing encoders typically specialize in only one or two of these capabilities; we therefore introduce ALPS, a pretrained visual state encoder that unifies all three in a single set of patch tokens. Using only still images and text, we pretrain a ViT-B/16 from scratch with language, reconstruction, ",pdfUrl:"https://arxiv.org/pdf/2610.30120",primaryCategory:"cs.CV",published:"2026-10-21T00:00:00Z"},{id:"2610.27450",title:"Ask to Distill: Learning to Synthesize Data for On-Policy Distillation",up:10,href:"https://arxiv.org/abs/2610.27450",abstract:"On-policy distillation (OPD) can succeed with surprisingly few training questions, motivating a view of questions as carriers of distributional knowledge transfer. How can we assess whether a newly generated question is valuable for distillation, and learn to generate better questions---without access to its correct answer? We introduce Ask-to-Distill (\\method), a framework that treats synthetic questions as distribution elicitors and optimizes the teacher supervision they expose along student-generated trajectories. A student-initialized synthesizer is optimized using a distributional surroga",pdfUrl:"https://arxiv.org/pdf/2610.27450",primaryCategory:"cs.AI",published:"2026-10-20T00:00:00Z"},{id:"2610.27592",title:"Real In, Real Out: What If We Only Use Real Data for Scene Text Editing?",up:9,href:"https://arxiv.org/abs/2610.27592",abstract:"Aiming to modify textual content while preserving the original style, Scene Text Editing (STE) has significant practical value in many applications. STE typically requires paired images before and after editing for training. However, recent approaches rely heavily on synthetic paired data and complex disentanglement strategies. They struggle to faithfully capture the diversity and complexity of natural scenes, often producing artifacts or hallucinations. In this work, we challenge the common practice and investigate whether STE can be driven by turning each real sample into its own paired supe",pdfUrl:"https://arxiv.org/pdf/2610.27592",primaryCategory:"cs.CV",published:"2026-10-20T00:00:00Z"},{id:"2610.28763",title:"Automating ML for Science: Can Frontier Agents Climb Scientific Hills in the Wild?",up:9,href:"https://arxiv.org/abs/2610.28763",abstract:"Frontier coding agents are increasingly framed as end-to-end automated researchers, and ML for science offers a demanding test of that promise: improving a scientific model often requires domain insight beyond routine ML engineering. We introduce Agent4Sci, a long-horizon testbed for measuring how far today's agents can improve the published best models on scientific ML benchmarks, spanning 20 benchmarks across 11 domains. Rather than ranking agents on a leaderboard, Agent4Sci asks what kinds of progress agents can make on these tasks under in-the-wild conditions, and where they fall short. Em",pdfUrl:"https://arxiv.org/pdf/2610.28763",primaryCategory:"cs.AI",published:"2026-10-20T00:00:00Z"},{id:"2610.19376",title:"DeLoop: Repeated Actions as Self-Supervision for Long-Horizon Agents",up:8,href:"https://arxiv.org/abs/2610.19376",abstract:"Language-model agents that run long tasks often redo work they have already done: they re-issue a tool call they made earlier and get back exactly the same observation, a step that adds no new information. We identify this failure as a loop. Loops appear natively in Qwen, Llama, and Gemini agents and become far more common once the agent's history is compressed to fit its context window. To reduce these loops, we propose DeLoop, a self-supervised training method. DeLoop builds on a simple observation: the agent's own rollout can provide the supervision needed to learn from its loops. We use a ",pdfUrl:"https://arxiv.org/pdf/2610.19376",primaryCategory:"cs.AI",published:"2026-10-14T00:00:00Z"},{id:"2610.27227",title:"Which Agent's Skill Should Change? Group-Relative Credit Assignment for Evolving Multi-Agent Teams",up:7,href:"https://arxiv.org/abs/2610.27227",abstract:"Cooperative language-model agents can improve without weight updates by revising reusable skills, but only if a shared team reward is traced to the responsible agent and skill. Existing methods credit the skills present in each trajectory, yet presence is not responsibility: a harmful skill active in successful runs still earns positive credit. We present \\textbf{GRSE}, \\textbf{G}roup-\\textbf{R}elative \\textbf{S}kill \\textbf{E}volution, which assigns behavioral credit by comparison: inspired by GRPO, it executes each question several times under the same skill libraries and contrasts the execu",pdfUrl:"https://arxiv.org/pdf/2610.27227",primaryCategory:"cs.CL",published:"2026-10-19T00:00:00Z"},{id:"W7171617880",title:"Machine-Speed Intrusion: A Detection Engineering Analysis of the July 2026 Hugging Face Agent Campaign",up:0,href:"https://doi.org/10.5281/zenodo.21686546",doi:"https://doi.org/10.5281/zenodo.21686546",year:2026,openalexId:"https://openalex.org/W7171617880"},{id:"W7171936549",title:"Could a Capability-Security Architecture Have Contained the July 2026 OpenAI-Hugging Face Agentic Exploit Chain?",up:0,href:"https://doi.org/10.5281/zenodo.21715175",doi:"https://doi.org/10.5281/zenodo.21715175",year:2026,openalexId:"https://openalex.org/W7171936549"},{id:"W7203931864",title:"hf-data-agent: a Hugging Face backed RAG data agent",up:0,href:"https://doi.org/10.5281/zenodo.22043399",doi:"https://doi.org/10.5281/zenodo.22043399",year:2026,openalexId:"https://openalex.org/W7203931864"}]}}]);